package com.ecopulse.repository; import com.ecopulse.model.ConsumptionRecord; import org.springframework.data.jpa.repository.JpaRepository; import java.time.Instant; import java.util.List; public interface ConsumptionRepository extends JpaRepository<ConsumptionRecord,Long>{ List<ConsumptionRecord> findByOrganizationIdAndRecordedAtBetweenOrderByRecordedAtAsc(Long org, Instant from, Instant to); List<ConsumptionRecord> findByBuildingIdAndRecordedAtBetweenOrderByRecordedAtAsc(Long building, Instant from, Instant to); }
